import { useState } from "react";
import { Link } from "react-router-dom";
import SummeryApi from "../common";


const SignUp = () => {
  const [formData, setFormData] = useState({});
  const [loading,isLoading]=useState(false);
  const [error,setError]=useState(false);

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.id]: e.target.value });
  };


  const handleSubmit = async (e) => {
    e.preventDefault();

    try{
      setLoading(true)
      console.log("Submitting to API:", SummeryApi.signup.url);
      
      const res = await fetch('http://localhost:8080/api/auth/signup', {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify(formData), 
      });
      const data=await res.json();
    }catch(err){
      setError(false);
      setLoading(false);


    } 
  
  };

  
  
  return (
    <div className="p-3 max-w-lg mx-auto">
      <h1 className="text-3xl text-center font-semibold my-6">Sign Up</h1>

      <form onSubmit={handleSubmit} className="flex flex-col gap-4">
        <input
          type="text"
          placeholder="username"
          id="username"
          className="bg-slate-100 p-3 rounded-lg"
          onChange={handleChange}
        />

        <input
          type="email"
          placeholder="email"
          id="email"
          className="bg-slate-100 p-3 rounded-lg"
          onChange={handleChange}
        />

        <input
          type="password"
          placeholder="password"
          id="password"
          className="bg-slate-100 p-3 rounded-lg"
          onChange={handleChange}
        />
        <button className="p-3 bg-slate-700 rounded-lg text-white hover:opacity-95 disabled:opacity-80">
          Sign Up
        </button>
        <div className="flex gap-2 mt-5">
          <p>Have an account?</p>
          <Link to="/sign-in">
            <span className="text-blue-500 hover:underline">Sign In</span>
          </Link>
        </div>
      </form>
    </div>
  );
};

export default SignUp;
